package com.phoenix.business.repository;import com.phoenix.business.domain.Attendance;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.*;import java.time.Instant;import java.util.*;public interface AttendanceRepository extends JpaRepository<Attendance,Long>{Optional<Attendance> findFirstByMemberIdAndStatusOrderByCheckedInAtDesc(Long id,Attendance.Status status);@EntityGraph(attributePaths={"member","recordedBy"})@Query("select a from Attendance a where a.checkedInAt>=:from and a.checkedInAt<:to and (:memberId is null or a.member.id=:memberId)")Page<Attendance> filter(@Param("from")Instant from,@Param("to")Instant to,@Param("memberId")Long memberId,Pageable p);List<Attendance> findByCheckedInAtBetween(Instant a,Instant b);@EntityGraph(attributePaths={"member","recordedBy"})List<Attendance> findTop10ByMemberIdOrderByCheckedInAtDesc(Long id);long countByCheckedInAtBetween(Instant a,Instant b);}
